{
  "name": "facting/fact",
  "description": "Append-oriented auditable business fact ledger for SmartResponsor platform capabilities",
  "type": "symfony-bundle",
  "license": "proprietary",
  "minimum-stability": "dev",
  "prefer-stable": true,
  "require": {
    "php": ">=8.4",
    "ext-json": "*",
    "symfony/framework-bundle": "^8.1",
    "symfony/runtime": "^8.1",
    "symfony/console": "^8.1",
    "symfony/http-foundation": "^8.1",
    "symfony/http-kernel": "^8.1",
    "symfony/routing": "^8.1",
    "symfony/security-bundle": "^8.1",
    "symfony/process": "^8.1",
    "symfony/dependency-injection": "^8.1",
    "symfony/config": "^8.1",
    "symfony/yaml": "^8.1",
    "symfony/twig-bundle": "^8.1",
    "accessing/access": "dev-master",
    "collectioning/collection": "dev-master",
    "cruding/crud": "dev-master",
    "tabling/table": "dev-master",
    "doctrine/doctrine-bundle": "^3.2",
    "doctrine/orm": "^3.3",
    "easycorp/easyadmin-bundle": "^5.0",
    "ext-pdo": "*",
    "ext-pdo_pgsql": "*",
    "interfacing/interface": "dev-master",
    "objecting/object": "dev-master",
    "viewing/view": "dev-master",
    "doctrine/doctrine-migrations-bundle": "^4.0",
    "ext-pdo_sqlite": "*"
  },
  "require-dev": {
    "league/openapi-psr7-validator": "^0.22.0",
    "nyholm/psr7": "^1.8",
    "phpunit/phpunit": "^10.0",
    "symfony/browser-kit": "^8.1",
    "friendsofphp/php-cs-fixer": "^3.95",
    "phpstan/phpstan": "^2.2"
  },
  "autoload": {
    "psr-4": {
      "App\\Facting\\": "src/",
      "App\\": "app/"
    }
  },
  "autoload-dev": {
    "psr-4": {
      "App\\Facting\\Tests\\": "tests/"
    }
  },
  "scripts": {
    "test": "phpunit -c phpunit.xml.dist",
    "cs:check": "php-cs-fixer fix --dry-run --diff --verbose",
    "cs:fix": "php-cs-fixer fix --verbose",
    "phpstan": "phpstan analyse -c phpstan.neon",
    "schema:validate": [
      "@php bin/console doctrine:schema:validate",
      "@php bin/console doctrine:migrations:up-to-date"
    ],
    "quality": [
      "@cs:check",
      "@phpstan",
      "@test"
    ]
  },
  "config": {
    "allow-plugins": {
      "symfony/runtime": false
    }
  },
  "repositories": [
    {
      "type": "path",
      "url": "../Accessing",
      "options": {
        "symlink": true,
        "versions": {
          "accessing/access": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Collectioning",
      "options": {
        "symlink": true,
        "versions": {
          "collectioning/collection": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Configuring",
      "options": {
        "symlink": true,
        "versions": {
          "configuring/config": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Cruding",
      "options": {
        "symlink": true,
        "versions": {
          "cruding/crud": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Interfacing",
      "options": {
        "symlink": true,
        "versions": {
          "interfacing/interface": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Objecting",
      "options": {
        "symlink": true,
        "versions": {
          "objecting/object": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Tabling",
      "options": {
        "symlink": true,
        "versions": {
          "tabling/table": "dev-master"
        }
      }
    },
    {
      "type": "path",
      "url": "../Viewing",
      "options": {
        "symlink": true,
        "versions": {
          "viewing/view": "dev-master"
        }
      }
    }
  ],
  "extra": {
    "symfony": {
      "bundle": "App\\Facting\\FactingBundle"
    }
  }
}
